# Streams Reader film v2 render kernel (generated by media/blender/kaggle/run.py; do not edit the copy on Kaggle).
# Downloads Blender (Linux LTS tarball), unpacks the embedded build_scene.py + shot + job, prepares the app screen
# capture as a JPEG sequence, runs every task in the job headless on the GPU, encodes animations to H.264 and
# leaves only small outputs (stills, segment videos, logs, timings) in /kaggle/working.
import base64
import glob
import io
import json
import os
import re
import shutil
import subprocess
import sys
import tarfile
import time
import urllib.request

PAYLOAD = "__PAYLOAD__"
T0 = time.time()
W = "/kaggle/working"
TMP = "/tmp/film"
LOG = {"started": time.strftime("%Y-%m-%d %H:%M:%S"), "tasks": []}
os.makedirs(TMP, exist_ok=True)
os.makedirs(f"{W}/logs", exist_ok=True)


def sh(cmd, timeout=None, log=None):
    print("+", cmd if isinstance(cmd, str) else " ".join(cmd), flush=True)
    t = time.time()
    with open(log, "w") if log else open(os.devnull, "w") as fh:
        p = subprocess.run(cmd, shell=isinstance(cmd, str), stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                           text=True, timeout=timeout)
        if log:
            fh.write(p.stdout)
    tail = p.stdout[-3000:]
    print(tail, flush=True)
    return p.returncode, round(time.time() - t, 1), tail


def save():
    LOG["elapsed_s"] = round(time.time() - T0, 1)
    json.dump(LOG, open(f"{W}/run_log.json", "w"), indent=1)


# 1. payload
with tarfile.open(fileobj=io.BytesIO(base64.b64decode(PAYLOAD)), mode="r:gz") as tf:
    tf.extractall(f"{TMP}/src")
JOB = json.load(open(f"{TMP}/src/job.json"))
LOG["job"] = JOB
rc, _, LOG["gpu"] = sh("nvidia-smi --query-gpu=name,memory.total,driver_version --format=csv")

# 2. Blender
series = JOB.get("blender", "4.5")
idx = urllib.request.urlopen(f"https://download.blender.org/release/Blender{series}/").read().decode()
vers = sorted({tuple(map(int, m)) for m in re.findall(rf"blender-{re.escape(series)}\.(\d+)-linux-x64\.tar\.xz", idx)})
patch = vers[-1][0]
name = f"blender-{series}.{patch}-linux-x64"
LOG["blender"] = name
t = time.time()
sh(f"cd {TMP} && curl -sSL -o b.tar.xz https://download.blender.org/release/Blender{series}/{name}.tar.xz && tar -xJf b.tar.xz && rm b.tar.xz")
LOG["blender_download_s"] = round(time.time() - t, 1)
BL = f"{TMP}/{name}/blender"
rc, _, missing = sh(f"ldd {BL} | grep 'not found' || true")
if "not found" in missing:
    sh("apt-get update -qq && apt-get install -y -qq libxi6 libxkbcommon0 libxxf86vm1 libxfixes3 libxrender1 libsm6 "
       "libgl1 libegl1 libxkbcommon-x11-0 libxrandr2 libxinerama1 libxcursor1 > /dev/null")
rc, _, LOG["blender_version"] = sh(f"{BL} -b --factory-startup -noaudio --version")

# 3. ffmpeg + app screen capture as a JPEG sequence (frame 0001 = capture time 0)
sh("pip install -q imageio-ffmpeg")
import imageio_ffmpeg  # noqa: E402
FF = imageio_ffmpeg.get_ffmpeg_exe()
os.makedirs(f"{TMP}/screen", exist_ok=True)
sh(f"curl -sSL -o {TMP}/app.webm {JOB['screen_url']}")
sh(f"{FF} -loglevel error -y -i {TMP}/app.webm -vf scale=780:1688 -q:v 2 {TMP}/screen/%04d.jpg")
LOG["screen_frames"] = len(glob.glob(f"{TMP}/screen/*.jpg"))
save()

# 4. tasks
deadline = T0 + JOB.get("max_hours", 11.3) * 3600
for i, task in enumerate(JOB["tasks"]):
    if time.time() > deadline:
        LOG["tasks"].append({"task": task, "skipped": "deadline"})
        continue
    out = f"{W}/stills" if task.get("frames") else f"{TMP}/frames/{task['segment']}"
    os.makedirs(out, exist_ok=True)
    cmd = [BL, "-b", "--factory-startup", "-noaudio", "-P", f"{TMP}/src/build_scene.py", "--",
           "--shot", f"{TMP}/src/{JOB['shot']}", "--segment", task["segment"], "--out", out,
           "--screen", f"{TMP}/screen", "--engine", task.get("engine", "cycles"),
           "--samples", str(task.get("samples", 0)), "--percent", str(task.get("percent", 100)),
           "--device", task.get("device", "OPTIX"), "--prefix", task.get("prefix", "")]
    if task.get("frames"):
        cmd += ["--frames", ",".join(str(f) for f in task["frames"])]
    if task.get("anim"):
        cmd += ["--anim"] + (["--range", task["range"]] if task.get("range") else [])
    if task.get("metrics"):
        cmd += ["--metrics"]
    if task.get("save"):
        cmd += ["--save", f"{W}/{task['segment']}.blend"]
    timeout = max(60, int(min(task.get("timeout", 4 * 3600), deadline - time.time())))
    tag = f"{i:02d}_{task.get('prefix', '')}{task['segment']}_{task.get('engine', 'cycles')}"
    try:
        rc, secs, tail = sh(cmd, timeout=timeout, log=f"{W}/logs/{tag}.log")
    except subprocess.TimeoutExpired:
        rc, secs, tail = -9, timeout, "timeout"
    rec = {"task": task, "rc": rc, "seconds": secs, "tail": tail[-1500:] if rc else ""}
    for tj in glob.glob(f"{out}/*{task['segment']}.timing.json"):
        rec["timing"] = json.load(open(tj))
        if not task.get("frames"):
            shutil.copy(tj, f"{W}/logs/{tag}.timing.json")
    for mj in glob.glob(f"{out}/*{task['segment']}.metrics.json"):
        shutil.copy(mj, f"{W}/logs/{tag}.metrics.json")
    if task.get("anim"):
        frames = sorted(glob.glob(f"{out}/{task['segment']}_*.png"))
        rec["frames_rendered"] = len(frames)
        if frames:
            first = int(re.search(r"_(\d+)\.png$", frames[0]).group(1))
            os.makedirs(f"{W}/video", exist_ok=True)
            suffix = f"_{task['range'].replace(':', '-')}" if task.get("range") else ""
            mp4 = f"{W}/video/{task['segment']}{suffix}.mp4"
            r2, s2, _ = sh(f"{FF} -loglevel error -y -framerate 30 -start_number {first} -i {out}/{task['segment']}_%04d.png "
                           f"-c:v libx264 -preset slow -crf 10 -pix_fmt yuv420p -colorspace bt709 -color_primaries bt709 "
                           f"-color_trc bt709 -movflags +faststart {mp4}")
            rec["encode_rc"], rec["encode_s"] = r2, s2
            rec["mp4_bytes"] = os.path.getsize(mp4) if os.path.exists(mp4) else 0
            # keep one still per second at full size for QA, drop the rest
            os.makedirs(f"{W}/stills", exist_ok=True)
            for fp in frames[::30]:
                shutil.copy(fp, f"{W}/stills/")
            shutil.rmtree(out, ignore_errors=True)
    LOG["tasks"].append(rec)
    save()

save()
print(json.dumps(LOG, indent=1)[-6000:])
